<script lang="ts">
import { onMount } from 'svelte';
import { api,ApiError } from '$lib/api';
import { workspace } from '$lib/workspace.svelte';
import { Badge,Button,Card,CardContent,CardDescription,CardHeader,CardTitle,Input } from '$lib/components/ui';
import { LibraryBig,Save,ShieldCheck } from '@lucide/svelte';
let settings:any=$state(null),safeguards:any=$state(null),busy=$state(false),error=$state(''),notice=$state('');
const base=()=>workspace.currentId?`/library/workspaces/${encodeURIComponent(workspace.currentId)}`:'';
async function load(){if(!workspace.currentId)return;try{const r=await api.get<any>(`${base()}/settings`);settings=r.settings;safeguards=r.safeguards;error='';}catch(e){error=e instanceof ApiError?e.message:'Unable to load Library settings';}}
async function save(){if(!settings)return;busy=true;try{const r=await api.patch<any>(`${base()}/settings`,{settings});settings=r.settings;safeguards=r.safeguards;notice='Library settings saved.';error='';}catch(e){error=e instanceof Error?e.message:'Save failed';}finally{busy=false;}}
onMount(async()=>{if(!workspace.workspaces.length)await workspace.load();if(!workspace.currentId&&workspace.workspaces[0])workspace.select(workspace.workspaces[0].id);await load();});
</script>
<svelte:head><title>Library Settings · OrbitFS</title></svelte:head>
<div class="mx-auto max-w-5xl space-y-5 p-4 md:p-6">
<div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-[.2em] text-primary">Base Knowledge System</p><h1 class="flex items-center gap-2 text-xl font-semibold"><LibraryBig class="size-5"/>Library Settings</h1><p class="text-sm text-muted-foreground">Workspace knowledge freshness, ingestion, retrieval and Studio-analysis budgets.</p></div><div class="flex gap-2"><select class="rounded-md border bg-background px-3 py-2 text-sm" value={workspace.currentId||''} onchange={async(e)=>{workspace.select(e.currentTarget.value);await load();}}>{#each workspace.workspaces as w}<option value={w.id}>{w.name}</option>{/each}</select><a class="rounded-md border px-3 py-2 text-sm hover:bg-accent" href="/library">Back to Library</a></div></div>
{#if error}<div class="rounded-md border border-destructive/30 bg-destructive/10 p-3 text-sm text-destructive">{error}</div>{/if}
{#if notice}<div class="rounded-md border border-emerald-500/30 bg-emerald-500/10 p-3 text-sm">{notice}</div>{/if}
{#if settings}
<Card><CardHeader><CardTitle>Knowledge freshness</CardTitle><CardDescription>Controls automatic freshness checks for cached knowledge projections. Per-item indexing locks still override these defaults.</CardDescription></CardHeader><CardContent class="grid gap-3 sm:grid-cols-2"><div><span class="text-sm font-medium">Freshness cache (ms)</span><Input type="number" min="1000" max="300000" bind:value={settings.freshnessMs}/></div><div><span class="text-sm font-medium">Max automatic refreshes / check</span><Input type="number" min="1" max="2000" bind:value={settings.maxFreshRefresh}/></div></CardContent></Card>
<Card><CardHeader><CardTitle>Knowledge ingestion</CardTitle><CardDescription>Limits import/ingestion discovery and registration batches. OrbitFS Cloud does not scan a server filesystem.</CardDescription></CardHeader><CardContent class="grid gap-3 sm:grid-cols-3"><div><span class="text-sm font-medium">Max items per ingest</span><Input type="number" min="50" max="10000" bind:value={settings.ingestMaxItems}/></div><div><span class="text-sm font-medium">Max registration batch</span><Input type="number" min="1" max="500" bind:value={settings.ingestBatch}/></div><label class="flex items-center justify-between rounded-md border p-3"><span><b>Index newly ingested knowledge</b><small class="block text-muted-foreground">Default for imported Library/Memory content.</small></span><input type="checkbox" bind:checked={settings.autoIndexKnowledge}/></label></CardContent></Card>
<Card><CardHeader><CardTitle>Retrieval defaults</CardTitle><CardDescription>Default result count and context budget for Studio and other knowledge consumers. MCP can consume these settings later when its cloud integration is reconnected.</CardDescription></CardHeader><CardContent class="grid gap-3 sm:grid-cols-2"><div><span class="text-sm font-medium">Default result limit</span><Input type="number" min="1" max="50" bind:value={settings.retrievalLimit}/></div><div><span class="text-sm font-medium">Default character budget</span><Input type="number" min="500" max="50000" bind:value={settings.retrievalMaxChars}/></div></CardContent></Card>
<Card><CardHeader><CardTitle>Studio analysis snapshot</CardTitle><CardDescription>Caps how much canonical Library/Memory material Studio can pull into one analysis run by default.</CardDescription></CardHeader><CardContent class="grid gap-3 sm:grid-cols-2"><div><span class="text-sm font-medium">Max Library items</span><Input type="number" min="1" max="500" bind:value={settings.analysisMaxItems}/></div><div><span class="text-sm font-medium">Max Library characters</span><Input type="number" min="10000" max="10000000" bind:value={settings.analysisMaxCharacters}/></div></CardContent></Card>
<Card><CardHeader><CardTitle class="flex items-center gap-2"><ShieldCheck class="size-4"/>Locked Library safeguards</CardTitle><CardDescription>Safety rules are shown here but cannot be disabled.</CardDescription></CardHeader><CardContent class="grid gap-2 sm:grid-cols-2"><div class="flex justify-between rounded-md border p-3"><span>Approval before authoritative writes</span><Badge variant="success">Always</Badge></div><div class="flex justify-between rounded-md border p-3"><span>Stale target validation</span><Badge variant="success">Always</Badge></div><div class="flex justify-between rounded-md border p-3"><span>Write verification + rollback</span><Badge variant="success">Always</Badge></div><div class="flex justify-between rounded-md border p-3"><span>Server filesystem mode</span><Badge>Disabled</Badge></div></CardContent></Card>
<div class="flex justify-end"><Button onclick={save} disabled={busy}><Save class="size-4"/>Save Library settings</Button></div>
{/if}
</div>